    [2545]={name="Malleable Chain Leggings",quality=2,ilvl=26,sourceType="quest_reward",instructions="Reward from the quest 'Apprentice's Duties'. Pick it over the other reward choices. Starts with James Halloran in Wetlands. Objective: Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",zone="Wetlands",questName="Apprentice's Duties",lore="I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."},
    [2546]={name="Royal Frostmane Girdle",quality=1,ilvl=11,reqLevel=6,sourceType="world_drop",instructions="Drops from Great Father Arctikus (rare spawn).",zone="Brewnall Village",npc="Great Father Arctikus"},
