    [12008]={name="Savannah Ring",quality=2,ilvl=28,reqLevel=23,sourceType="world_drop",instructions="World drop around level 23-29."},
    [12018]={name="Conservator Helm",quality=2,ilvl=54,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12019]={name="Cerulean Talisman",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="World drop around level 26-33."},
    [12020]={name="Thallium Choker",quality=2,ilvl=36,reqLevel=31,sourceType="world_drop",instructions="World drop around level 32-37."},
    [12021]={name="Shieldplate Sabatons",quality=2,ilvl=54,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12022]={name="Iridium Chain",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42."},
    [12040]={name="Forest Pendant",quality=2,ilvl=38,reqLevel=33,sourceType="world_drop",instructions="World drop around level 33-39."},
    [12047]={name="Spectral Necklace",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31."},
    [12049]={name="Splintsteel Armor",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Ribbly Screwspigot'. Pick it over the other reward choices. Starts with Yuka Screwspigot in Burning Steppes. Objective: Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",zone="Blackrock Depths",questName="Ribbly Screwspigot",lore="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."},
    [12051]={name="Brazen Gauntlets",quality=2,ilvl=54,sourceType="quest_reward",instructions="Reward from the quest 'A Little Slime Goes a Long Way'. Pick it over the other reward choices. Starts with Laris Geardawdle in Ironforge. Objective: Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.If you have trouble finding them, perhaps try to get more clues from Laris.",zone="Ironforge",questName="A Little Slime Goes a Long Way",lore="I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."},
    [12052]={name="Ring of the Moon",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22."},
