    [19323]={name="The Unstoppable Force",quality=4,ilvl=65,reqLevel=60,sourceType="vendor",instructions="Bought from Gaelden Hammersmith.",zone="Alterac Valley",npc="Gaelden Hammersmith",proc="Chance on hit: Stuns target for 1 sec."},
    [19324]={name="The Lobotomizer",quality=4,ilvl=65,reqLevel=60,sourceType="vendor",instructions="Bought from Gaelden Hammersmith.",zone="Alterac Valley",npc="Gaelden Hammersmith",proc="Chance on hit: Wounds the target for 200 to 300 damage and lowers Intellect of target by 25 for 30 sec."},
