    [19822]={name="Zandalar Vindicator's Breastplate",quality=4,ilvl=65,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Vindicator's Breastplate'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Vindicator's Breastplate",lore="The vindicator's symbol of power is the breastplate."},
    [19823]={name="Zandalar Vindicator's Belt",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Vindicator's Belt'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Vindicator's Belt",lore="Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."},
    [19824]={name="Zandalar Vindicator's Armguards",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Vindicator's Armguards'. Starts with Jin'rokh the Breaker in Stranglethorn Vale. Objective: Bring Jin'rokh the Breaker a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Vindicator's Armguards",lore="Vengeance is power. The Zandalar vindicator is such power."},
