    [22935]={name="Touch of Frost",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Anub'Rekhan.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22940]={name="Icebane Pauldrons",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22954]={name="Kiss of the Spider",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [22981]={name="Gluth's Missing Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gluth.",zone="Naxxramas",npc="Gluth",lore="A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."},
    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Use: Reduces the threat you generate by [35 - max(0, Level - 60)]% for 20 sec. (2 Min Cooldown)"},
    [23018]={name="Signet of the Fallen Defender",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Instructor Razuvious.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."},
    [23019]={name="Icebane Helmet",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Heigan the Unclean.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23023]={name="Sadist's Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gothik the Harvester.",zone="Naxxramas",npc="Gothik the Harvester",lore="Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."},
    [23028]={name="Hailstone Band",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [23033]={name="Icy Scale Coif",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Heigan the Unclean.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23038]={name="Band of Unnatural Forces",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Loatheb.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23040]={name="Glyph of Deflection",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases the block value of your shield by 235 for 20 sec. (2 Min Cooldown)"},
    [23041]={name="Slayer's Crest",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases attack power by 260 for 20 sec. (2 Min Cooldown)"},
    [23059]={name="Ring of the Dreadnaught",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23078]={name="Gauntlets of Undead Slaying",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Argent Dawn Gloves'. Pick it over the other reward choices. Starts with Argent Outfitter in Eastern Plaguelands. Objective: ProgressIf you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.",zone="Eastern Plaguelands",questName="Argent Dawn Gloves"},
    [23087]={name="Breastplate of Undead Slaying",quality=3,ilvl=63,reqLevel=58,sourceType="world_drop",instructions="Drops from Shadow of Doom (rare elite).",npc="Shadow of Doom"},
    [23090]={name="Bracers of Undead Slaying",quality=3,ilvl=63,reqLevel=58,sourceType="world_drop",instructions="Drops from Lumbering Horror (rare spawn).",npc="Lumbering Horror"},
    [23206]={name="Mark of the Champion",quality=4,ilvl=90,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Kel'Thuzad'. Pick it over the other reward choices. The quest is in Naxxramas. Objective: Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.",zone="Naxxramas",questName="The Fall of Kel'Thuzad",lore="Struck for the war against the Scourge and the Old Gods. It does nothing at all against anything else, which is the point of the mark."},
